// Built-in local catalogue: serves every content catalogue from the open asset pack (public/packs/open) and the
// plain-data catalogues in src/data, so all features work with no provider configured. Everything here is
// original or generated by scripts/gen-*.mjs. Data is imported statically (no filesystem access at runtime), so
// the standalone build traces only these JSON files.
import "server-only";
import type { CatalogItem, FeedName, LookKind, Track } from "@/lib/content/types";
import type { RemoteStickerCategory } from "@/lib/content/validate";
import { ART_STYLES } from "@/data/content/artStyles";
import { FILTER_DEFS } from "@/data/filters";
import { FACE_PRESETS } from "@/lib/face/presets";
import { MAKEUP_CATEGORIES } from "@/data/camera/beauty";
import home from "@/data/home.json";
import discover from "@/data/discover.json";
import manifest from "../../../public/packs/open/manifest.json";
import type { CatalogQuery, ContentProvider } from "./types";

interface Entry { path: string; meta?: Record<string, unknown> }
const KINDS = (manifest as unknown as { kinds: Record<string, Record<string, Entry>> }).kinds;
const BASE = process.env.NEXT_PUBLIC_BASE_PATH ?? "";
const packUrl = (path: string) => `${BASE}/packs/open/${path}`;
const url = (kind: string, id: string) => (KINDS[kind]?.[id] ? packUrl(KINDS[kind][id].path) : undefined);
const entries = (kind: string) => Object.entries(KINDS[kind] ?? {});

// ---------------------------------------------------------------- catalogues

interface MusicMeta { title: string; artist?: string; mood?: string; bpm?: number; duration?: number }
const TRACKS: Track[] = entries("music").map(([id, e]) => {
  const m = (e.meta ?? {}) as unknown as MusicMeta;
  return { id, title: m.title ?? id, artist: m.artist, mood: m.mood, bpm: m.bpm, duration: m.duration, url: packUrl(e.path) };
});

interface StickerMeta { id: number; name: string; def?: { items?: { drawType?: string }[] } }
const STICKERS = entries("sticker").map(([slug, e]) => {
  const m = e.meta as unknown as StickerMeta;
  return { slug, id: m.id, name: m.name, def: m.def, thumbnail: url("sticker-thumb", slug) ?? "", drawTypes: new Set((m.def?.items ?? []).map((i) => i.drawType ?? "")) };
});
type St = (typeof STICKERS)[number];
const stickerItem = (s: St, kind: string): CatalogItem => ({ id: `sticker-${s.slug}`, name: s.name, thumbnail: s.thumbnail, kind, href: `/?sticker=${s.id}` });
const isAccessory = (s: St) => s.drawTypes.has("FACE_3D");
const isFacePaint = (s: St) => s.drawTypes.has("FACE_MASK");
const isLens = (s: St) => s.drawTypes.has("COLOR_LENS");
const isBackground = (s: St) => s.drawTypes.has("BACKGROUND");

const STICKER_CATEGORIES: RemoteStickerCategory[] = [
  { id: -201, text: "Cute", stickers: STICKERS.filter((s) => s.drawTypes.has("FACE") || isAccessory(s)) },
  { id: -202, text: "Face paint", stickers: STICKERS.filter(isFacePaint) },
  { id: -203, text: "Eyes", stickers: STICKERS.filter((s) => isLens(s) || /eye|lash/i.test(s.slug)) },
  { id: -204, text: "Beauty", stickers: STICKERS.filter((s) => s.drawTypes.has("") || s.drawTypes.has("BUILT_IN") || s.drawTypes.size === 0) },
  { id: -205, text: "Scenes", stickers: STICKERS.filter(isBackground) },
].map((c) => ({ ...c, server: true, stickers: c.stickers.map((s) => ({ id: s.id, name: s.name, thumbnail: s.thumbnail, json: s.def })) }))
  .filter((c) => c.stickers.length > 0);

const FILTERS: CatalogItem[] = FILTER_DEFS.map((f) => ({ id: `filter-${f.key}`, name: f.name, thumbnail: url("filter-thumb", f.key), kind: "filter", href: `/?filter=${f.id}`, tags: [f.group] }));
const FACE: CatalogItem[] = FACE_PRESETS.map((p) => ({ id: `face-${p.key}`, name: p.label, thumbnail: url("feed", `style-${p.key}`), kind: "transform", href: `/?beauty=${p.key}` }));
const MAKEUP: CatalogItem[] = MAKEUP_CATEGORIES.flatMap((c) => c.contents.filter((ct) => ct.key !== "none").map((ct) => ({
  id: `makeup-${c.key}-${ct.key}`, name: `${c.label}: ${ct.label}`, thumbnail: swatch(ct.bg ?? c.bg), kind: "makeup",
})));
const BRUSHES: CatalogItem[] = entries("brush").map(([id, e]) => ({ id: `brush-${id}`, name: id.replace(/-/g, " ").replace(/^./, (c) => c.toUpperCase()), thumbnail: packUrl(e.path), kind: "brush" }));
const FONTS: CatalogItem[] = entries("font").map(([id, e]) => ({ id: `font-${id}`, name: String(e.meta?.family ?? id), kind: "text", tags: ["OFL-1.1"] }));
const BACKGROUNDS: CatalogItem[] = [
  ...STICKERS.filter(isBackground).map((s) => stickerItem(s, "background")),
  ...entries("feed").filter(([id]) => /^post-\d+$/.test(id)).map(([id, e], i) => ({ id: `backdrop-${id}`, name: `Backdrop ${i + 1}`, thumbnail: packUrl(e.path), kind: "background" })),
];
const MUSIC_ITEMS: CatalogItem[] = TRACKS.map((t) => ({ id: `music-${t.id}`, name: t.title, kind: "music", tags: t.mood ? [t.mood] : undefined }));
const ADJUST: CatalogItem[] = ["Brightness", "Contrast", "Saturation", "Warmth", "Tint", "Highlights", "Shadows", "Clarity", "Sharpen", "Fade", "Grain", "Vignette"]
  .map((n) => ({ id: `adjust-${n.toLowerCase()}`, name: n, kind: "adjust" }));
const CUTOUT: CatalogItem[] = [["person", "Person"], ["hair", "Hair"], ["background", "Background"], ["sky", "Sky"]]
  .map(([id, name]) => ({ id: `cutout-${id}`, name, kind: "cutout" }));

/** Collage templates with a generated SVG preview of each layout. */
const TEMPLATES: CatalogItem[] = entries("collage").flatMap(([id, e]) => {
  const m = e.meta as { photos: number; layouts: number[][][] } | undefined;
  if (!m) return [];
  return m.layouts.slice(0, 3).map((cells, i) => ({
    id: `collage-${m.photos}-${i + 1}`, name: `${m.photos} photos · ${["Grid", "Stack", "Feature"][i] ?? `Layout ${i + 1}`}`, kind: "template",
    thumbnail: layoutSvg(cells), href: "/gallery?mode=collage", tags: [id],
  }));
});

function swatch(color: string): string {
  const c = /^#[0-9a-f]{6}$/i.test(color) ? color : "#888888";
  return `data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" fill="#1f2229"/><circle cx="32" cy="32" r="20" fill="${c}"/></svg>`)}`;
}
function layoutSvg(cells: number[][]): string {
  const g = 2, s = 64;
  const rects = cells.map(([x, y, w, h]) => `<rect x="${(x * s + g).toFixed(1)}" y="${(y * s + g).toFixed(1)}" width="${Math.max(1, w * s - 2 * g).toFixed(1)}" height="${Math.max(1, h * s - 2 * g).toFixed(1)}" rx="3" fill="#2a2e37"/>`).join("");
  return `data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="6" fill="#15171c"/>${rects}</svg>`)}`;
}

const LOOKS: Record<Exclude<LookKind, "store" | "templates">, CatalogItem[]> = {
  sticker: STICKERS.map((s) => stickerItem(s, "sticker")),
  effect: STICKERS.map((s) => stickerItem(s, "effect")),
  accessory: STICKERS.filter(isAccessory).map((s) => stickerItem(s, "accessory")),
  facepaint: STICKERS.filter((s) => isFacePaint(s) || isLens(s)).map((s) => stickerItem(s, "facepaint")),
  transform: FACE,
  beauty: FACE,
  makeup: MAKEUP,
  filter: FILTERS,
  brush: BRUSHES,
  text: FONTS,
  template: TEMPLATES,
  music: MUSIC_ITEMS,
  background: BACKGROUNDS,
  adjust: ADJUST,
  cutout: CUTOUT,
};

// ---------------------------------------------------------------- query helpers

const norm = (s: string) => s.toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "");
function matches(q: string, ...fields: (string | string[] | undefined)[]) {
  if (!q) return true;
  const hay = norm(fields.flat().filter(Boolean).join(" "));
  return norm(q).split(/\s+/).every((w) => hay.includes(w.replace(/^#/, "")));
}
const page = <T,>(arr: T[], q: CatalogQuery) => arr.slice(q.offset, q.offset + q.limit);
const filterItems = (items: CatalogItem[], q: CatalogQuery) => page(items.filter((i) => matches(q.q, i.name, i.kind, i.tags)), q);

function searchAll(q: CatalogQuery): CatalogItem[] {
  if (!q.q) return page(LOOKS.sticker, q);
  const seen = new Set<string>();
  const all = Object.values(LOOKS).flat().filter((i) => !seen.has(i.id) && (seen.add(i.id), true));
  return filterItems(all, q);
}

export const localProvider: ContentProvider = {
  name: "local",
  music: async (q) => page(TRACKS.filter((t) => matches(q.q, t.title, t.artist, t.mood)), q),
  artStyles: async (q) => page(ART_STYLES.filter((s) => matches(q.q, s.name, s.about)), q),
  looks: async (kind, q) => (kind === "store" ? searchAll(q) : filterItems(kind === "templates" ? TEMPLATES : LOOKS[kind], q)),
  stickers: async (q) => STICKER_CATEGORIES.map((c) => ({ ...c, stickers: c.stickers.filter((s) => matches(q.q, s.name)) })).filter((c) => c.stickers.length),
  templates: async (q) => filterItems(TEMPLATES, q),
  feed: async (name: FeedName) => (name === "home" ? home : discover),
};
